/**
 * Returns the current Member, today's daily-quota state, and any
claim-eligible unclaimed Scan IDs that match the caller's anon
session cookie. When the authenticated user has not yet chosen a
username, `member` is null and `needsUsername` is true.

 * @summary Get the current Member
 */
export const getMeResponseMemberOneUsernameRegExp = new RegExp(
  "^[a-z0-9_]{3,20}$",
);
export const getMeResponseDailyQuotaUsedMin = 0;

export const GetMeResponse = zod
  .object({
    member: zod.union([
      zod.object({
        id: zod.string().uuid(),
        username: zod.string().regex(getMeResponseMemberOneUsernameRegExp),
        createdAt: zod.coerce.date(),
      }),
      zod.null(),
    ]),
    needsUsername: zod.boolean(),
    dailyQuota: zod
      .object({
        used: zod.number().min(getMeResponseDailyQuotaUsedMin),
        limit: zod.number().min(1).describe("Member limit per UTC day (25)."),
        resetAt: zod.coerce.date().describe("Next UTC midnight."),
      })
      .describe("Member daily-quota state keyed by UTC day."),
    claimableScanIds: zod
      .array(zod.string().uuid())
      .describe(
        "Unclaimed Scan IDs that match the caller's anon session cookie.",
      ),
  })
  .describe(
    "Current Member state. When the authenticated user has not yet chosen a\nusername, `member` is null and `needsUsername` is true.\n",
  );

/**
 * First-sign-in step. Validates the chosen username against
`^[a-z0-9_]{3,20}$` and case-insensitive uniqueness. On success the
Member row is created and the username becomes immutable.

 * @summary Set the current Member's username
 */
export const setMyUsernameBodyUsernameMin = 3;
export const setMyUsernameBodyUsernameMax = 20;

export const setMyUsernameBodyUsernameRegExp = new RegExp("^[a-z0-9_]{3,20}$");

export const SetMyUsernameBody = zod.object({
  username: zod
    .string()
    .min(setMyUsernameBodyUsernameMin)
    .max(setMyUsernameBodyUsernameMax)
    .regex(setMyUsernameBodyUsernameRegExp),
});

export const setMyUsernameResponseMemberUsernameRegExp = new RegExp(
  "^[a-z0-9_]{3,20}$",
);

export const SetMyUsernameResponse = zod.object({
  member: zod.object({
    id: zod.string().uuid(),
    username: zod.string().regex(setMyUsernameResponseMemberUsernameRegExp),
    createdAt: zod.coerce.date(),
  }),
});
